CREATE FUNCTION salud_u.obtener_historia_longitudinal_area(p_paciente uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=salud_u,pg_temp AS $$
DECLARE personal uuid:=salud_u.id_mi_personal_activo(); paciente record; ids uuid[];
BEGIN
 IF NOT(salud_u.tiene_rol_actor('REVIEW_DOCTOR') OR salud_u.tiene_rol_actor('SPECIALIST')) THEN RAISE EXCEPTION 'MEDICO_NO_AUTORIZADO' USING ERRCODE='42501'; END IF;
 SELECT * INTO paciente FROM salud_u.paciente WHERE id=p_paciente AND archivado_en IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'PACIENTE_SIN_ACCESO_CLINICO' USING ERRCODE='P0002'; END IF;
 SELECT array_agg(e.id) INTO ids FROM salud_u.encuentro_clinico e WHERE e.id_paciente=p_paciente AND ((salud_u.tiene_rol_actor('REVIEW_DOCTOR') AND e.tipo_encuentro='INITIAL') OR (salud_u.tiene_rol_actor('SPECIALIST') AND ((e.tipo_encuentro='SPECIALTY' AND EXISTS(SELECT 1 FROM salud_u.especialidad_personal ep WHERE ep.id_personal=personal AND ep.id_especialidad=e.id_especialidad AND ep.vigente_desde<=current_date AND (ep.vigente_hasta IS NULL OR ep.vigente_hasta>=current_date))) OR (e.tipo_encuentro='INITIAL' AND EXISTS(SELECT 1 FROM salud_u.derivacion d WHERE d.id_encuentro_origen=e.id AND d.id_personal_asignado=personal)))));
 IF ids IS NULL THEN RAISE EXCEPTION 'PACIENTE_SIN_ACCESO_CLINICO' USING ERRCODE='P0002'; END IF;
 RETURN jsonb_build_object('patient',jsonb_build_object('id',paciente.id,'carnet',paciente.carnet,'registrationCode',paciente.codigo_registro,'fullName',concat_ws(' ',paciente.nombres,paciente.apellidos),'birthDate',paciente.fecha_nacimiento,'phone',paciente.telefono,'email',paciente.email),'encounters',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',e.id,'appointment_id',e.id_cita,'status',e.estado,'encounter_type',e.tipo_encuentro,'occurred_at',e.ocurrido_en,'chief_complaint',e.motivo_consulta,'assessment',e.evaluacion,'instructions',e.indicaciones,'follow_up_text',e.seguimiento,'specialty',s.nombre,'reviewHistory',(SELECT f.datos FROM salud_u.ficha_revision_version f WHERE f.id_encuentro=e.id),'specialtyHistory',(SELECT f.datos FROM salud_u.version_ficha_especialidad f WHERE f.id_encuentro=e.id)) ORDER BY e.ocurrido_en DESC) FROM salud_u.encuentro_clinico e LEFT JOIN salud_u.especialidad s ON s.id=e.id_especialidad WHERE e.id=ANY(ids)),'[]'::jsonb),'diagnoses',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',d.id,'encounter_id',d.id_encuentro,'label',d.texto_libre,'is_primary',d.es_principal)) FROM salud_u.diagnostico_encuentro d WHERE d.id_encuentro=ANY(ids)),'[]'::jsonb),'documents',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',d.id,'encounter_id',d.id_encuentro,'document_type_code',d.tipo_documento,'status',d.estado,'original_filename',d.nombre_original,'mime_type',d.tipo_mime,'size_bytes',d.tamano_bytes,'study_date',d.fecha_estudio,'description',d.descripcion,'uploaded_at',d.cargado_en) ORDER BY d.cargado_en DESC) FROM salud_u.documento_clinico d WHERE d.id_encuentro=ANY(ids) AND d.estado='AVAILABLE'),'[]'::jsonb),'appointments',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',c.id,'status',c.estado,'appointment_type',c.tipo_cita,'scheduled_for',c.programada_para,'specialty',s.nombre,'isAssignedToMe',(c.id_personal_asignado=personal)) ORDER BY c.programada_para DESC) FROM salud_u.cita c JOIN salud_u.cupo_disponibilidad cupo ON cupo.id=c.id_cupo LEFT JOIN salud_u.especialidad s ON s.id=cupo.id_especialidad WHERE c.id_paciente=p_paciente AND c.id_personal_asignado=personal),'[]'::jsonb));
END $$;
GRANT EXECUTE ON FUNCTION salud_u.obtener_historia_longitudinal_area(uuid) TO ${runtime_role};
